import {
  ApplicationRef,
  inject,
  Injectable,
  NgZone,
  signal,
} from '@angular/core';
import { catchError, Observable } from 'rxjs';
import { filter, map, tap } from 'rxjs/operators';
import { getWsConnect } from './web-socket-client';

interface Data {
  message?: string;
  status?: string;
}
export interface Message {
  text: string;
  sent: Date;
}

@Injectable({ providedIn: 'root' })
export class ChatClient {
  #status = signal<'not connected' | 'connected' | 'failed'>('not connected');
  status = this.#status.asReadonly();
  #messages = signal<Message[]>([]);
  messages = this.#messages.asReadonly();
  appRef = inject(ApplicationRef);
  ngZone = inject(NgZone);

  connect() {
    getWsConnect(() => this.ngZone.run(() => this.appRef.tick()))
      .pipe(
        catchError((err) => {
          console.error(err);
          this.#status.set('failed');
          return new Observable<Data>((subscriber) => subscriber.complete());
        }),
        tap(() => {
          if (this.#status() === 'not connected') {
            this.#messages.set([]);
            this.#status.set('connected');
          }
        }),
        filter((data) => 'message' in data),
        map((data) => ({ text: data.message ?? '', sent: new Date() })),
      )
      .subscribe((message) => {
        this.#messages.update((value) => [...value, message]);
      });
  }
}

import { Observable } from 'rxjs';
import { webSocket } from 'rxjs/webSocket';

interface Data {
  message?: string;
  status?: string;
}

declare global {
  interface Window {
    mockedClient?: (data: Data) => void;
    e2e: unknown;
  }
}

export const getWsConnect = (triggerCd: () => void): Observable<Data> => {
  if (window.e2e) {
    console.info('WebSocket is controlled by the E2E Framework');
    return new Observable<Data>((subscriber) => {
      window.mockedClient = (data: Data) => {
        subscriber.next(data);
        triggerCd();
      };
    });
  } else {
    return webSocket<Data>('ws://localhost:8080');
  }
};

import { createReducer, on } from '@ngrx/store';
import { diaryActions } from './diary.actions';

export const diaryFeatureKey = 'diary';

export interface Diary {
  id: number;
  title: string;
  description: string;
}

export interface DiaryEntry {
  id: number;
  diaryId: number;
  date: Date;
  content: string;
}

export type DiaryWithEntries = Diary & { entries: DiaryEntry[] };

export interface DiaryResponse {
  diaries: DiaryWithEntries[];
}

export interface DiaryState {
  diaries: Diary[];
  diaryEntries: DiaryEntry[];
  loaded: boolean;
}

const initialState: DiaryState = {
  diaries: [],
  diaryEntries: [],
  loaded: false,
};

export const diaryReducer = createReducer<DiaryState>(
  initialState,
  on(
    diaryActions.loadSuccess,
    (state, { diaryResponse }): DiaryState => ({
      ...state,
      loaded: true,
      diaries: diaryResponse.diaries.map((diary) => {
        const { id, title, description } = diary;
        return { id, title, description };
      }),
      diaryEntries: diaryResponse.diaries.map((diary) => diary.entries).flat(),
    }),
  ),
  on(diaryActions.addSuccess, (state, action): DiaryState => {
    const { id, title, description } = action.diaryWithEntries;
    return {
      ...state,
      diaries: [...state.diaries, { id, title, description }],
    };
  }),
);

