  withComputed((state) => {
    return {
      status: computed(() => {
        const status: Record<AnswerStatus, number> = {
          unanswered: 0,
          correct: 0,
          incorrect: 0,
        };

        for (const question of state.questions()) {
          if (question.givenAnswer) {
            status[
              question.givenAnswer === question.correctAnswer
                ? 'correct'
                : 'incorrect'
            ]++;
          } else {
            status['unanswered']++;
          }
        }

        return status;
      }),
    };
